const List<String> builtInQuestJson = <String>[
  r'''{"id":"market_day","title":"Market Day at Mile 12","subject":"math","level":"JSS1","blurb":"Run Mama Tunde's tomato stall for one day. Buy, price and sell without losing her money.","icon":"storefront","colors":["#E65100","#FFB300"],"xp":30,"stats":[{"id":"money","label":"Naira","icon":"payments","start":10000,"min":0,"format":"naira"},{"id":"rep","label":"Trust","icon":"favorite","start":0}],"cast":{"mama":{"name":"Mama Tunde","role":"Stall owner","color":"#E65100"},"kola":{"name":"Baba Kola","role":"Supplier","color":"#2E7D32"},"ngozi":{"name":"Madam Ngozi","role":"Restaurant owner","color":"#6A1B9A"},"bisi":{"name":"Bisi","role":"Your cousin","color":"#0277BD"}},"start":"intro","scenes":{"intro":{"kind":"say","text":"It is 6 a.m. at Mile 12 Market in Lagos. Mama Tunde hands you {money} and her notebook. \"Today the stall is yours. Buy well, sell well, and bring me back more than I gave you.\"","next":"supplier","speaker":"mama","bg":"market"},"supplier":{"kind":"say","text":"\"Fresh tomatoes!\" Baba Kola calls. \"One basket is ₦2,500. Buy 3 baskets and I will give you the 4th basket at half price.\"","next":"q_cost","speaker":"kola","bg":"market"},"q_cost":{"kind":"input","text":"You want exactly 4 baskets. Using Baba Kola's offer, how much do you pay in total (in naira)?","answer":8750,"tolerance":0,"right":{"next":"pack","feedback":"Correct. 3 baskets at ₦2,500 is ₦7,500. The 4th basket is half of ₦2,500, which is ₦1,250. Total: ₦8,750.","effects":{"money":-8750}},"wrong":{"next":"pack","feedback":"Not quite. 3 baskets at ₦2,500 is ₦7,500. The 4th is half price: ₦1,250. So the total is ₦8,750, and you pay it.","effects":{"money":-8750}},"speaker":"kola","bg":"market","unit":"₦","hint":"3 full baskets, then 1 half-price basket"},"pack":{"kind":"say","text":"Baba Kola loads four baskets onto your stall. \"Each basket makes 20 small heaps,\" he says. \"Count well.\"","next":"q_heaps","speaker":"kola","bg":"market"},"q_heaps":{"kind":"input","text":"How many heaps of tomatoes do you have to sell in total?","answer":80,"tolerance":0,"right":{"next":"q_break","feedback":"Correct. 4 baskets x 20 heaps = 80 heaps."},"wrong":{"next":"q_break","feedback":"Not quite. 4 baskets x 20 heaps = 80 heaps."},"speaker":"bisi","bg":"market","hint":"4 x 20"},"q_break":{"kind":"input","text":"Bisi whispers: \"Mama says never sell below what a heap cost you.\" You spent ₦8,750 on 80 heaps. What did one heap cost, to the nearest naira?","answer":109,"tolerance":1,"right":{"next":"q_change","feedback":"Correct. 8,750 divided by 80 is 109.375, so about ₦109 per heap. Anything below that is a loss."},"wrong":{"next":"q_change","feedback":"Not quite. 8,750 divided by 80 is 109.375, so about ₦109 per heap. Anything below that is a loss."},"speaker":"bisi","bg":"market","unit":"₦","hint":"Divide the total cost by the number of heaps"},"q_change":{"kind":"input","text":"Your first customer buys 3 heaps at ₦120 each and pays with a ₦500 note. How much change do you give her?","answer":140,"tolerance":0,"right":{"next":"price","feedback":"Correct. 3 x 120 = 360, and 500 - 360 = ₦140 change.","effects":{"rep":1}},"wrong":{"next":"price","feedback":"Not quite. 3 x 120 = 360, and 500 - 360 = ₦140 change. She waits, a little annoyed.","effects":{"rep":-1}},"speaker":"bisi","bg":"market","unit":"₦","hint":"First find the cost of 3 heaps"},"price":{"kind":"choice","text":"The market is filling up. What price will you put on each heap?","choices":[{"text":"₦100 per heap. Sell fast.","next":"sold100","learn":false,"feedback":"₦100 is below the ₦109 cost of a heap. You will sell out, but you will lose money on every heap."},{"text":"₦130 per heap.","next":"sold130","learn":true,"feedback":"A fair price. It is above cost, and buyers will not complain."},{"text":"₦150 per heap.","next":"sold150","learn":true,"feedback":"A strong price. Good profit, and the heaps still look like good value."},{"text":"₦250 per heap. Tomatoes are scarce today.","next":"sold250","learn":false,"feedback":"Too high. Buyers walk to the next stall and your heaps wait in the sun."}],"speaker":"mama","bg":"market"},"sold100":{"kind":"say","text":"By 9 a.m. everything is gone. 80 heaps at ₦100 brings in ₦8,000. That is less than the ₦8,750 you paid for them.","next":"ngozi","bg":"market","effects":{"money":8000,"rep":1}},"sold130":{"kind":"say","text":"By midday you have sold all 80 heaps at ₦130. That brings in ₦10,400.","next":"ngozi","bg":"market","effects":{"money":10400,"rep":1}},"sold150":{"kind":"say","text":"By afternoon you have sold all 80 heaps at ₦150. That brings in ₦12,000.","next":"ngozi","bg":"market","effects":{"money":12000,"rep":2}},"sold250":{"kind":"say","text":"Only 30 heaps sell at ₦250, bringing in ₦7,500. The rest go soft in the heat and you throw them away.","next":"ngozi","bg":"market","effects":{"money":7500,"rep":-1}},"ngozi":{"kind":"say","text":"Madam Ngozi, who runs a restaurant, stops by. \"I like your stall. I will be a regular customer, but I want 10% off the ₦1,500 you quoted me for ten heaps.\"","next":"q_disc","speaker":"ngozi","bg":"market"},"q_disc":{"kind":"input","text":"How much does Madam Ngozi pay after her 10% discount on ₦1,500?","answer":1350,"tolerance":0,"right":{"next":"costs","feedback":"Correct. 10% of 1,500 is 150, and 1,500 - 150 = ₦1,350. She is delighted and promises to come back.","effects":{"rep":2}},"wrong":{"next":"costs","feedback":"Not quite. 10% of 1,500 is 150, and 1,500 - 150 = ₦1,350. She decides to shop elsewhere next time.","effects":{"rep":-1}},"speaker":"ngozi","bg":"market","unit":"₦","hint":"Find 10% by dividing by 10"},"costs":{"kind":"say","text":"Time to pack up. You pay ₦500 for transport home and ₦300 for the market levy collector.","next":"check","bg":"market","effects":{"money":-800}},"check":{"kind":"branch","branches":[{"next":"end_great","if":[{"stat":"money","op":">=","value":12000}]},{"next":"end_ok","if":[{"stat":"money","op":">=","value":10000}]},{"next":"end_bad"}]},"end_great":{"kind":"end","title":"A proper trader","summary":"You gave Mama Tunde back her ₦10,000 with a clear profit. You priced above cost, checked every sum and kept your customers happy. She hands you the notebook for next Saturday.","outcome":"good","bg":"market"},"end_ok":{"kind":"end","title":"You broke even and a bit more","summary":"You returned Mama Tunde's money with a small profit. Next time, check your cost per heap first and price with more confidence.","outcome":"ok","bg":"market"},"end_bad":{"kind":"end","title":"A hard lesson","summary":"You came home with less than you started with. Know your cost per item before you set a price: too low loses money, too high loses customers.","outcome":"bad","bg":"market"}}}''',
  r'''{"id":"danfo_hustle","title":"The Danfo Hustle","subject":"math","level":"JSS2","blurb":"You have 60 minutes to reach your exam across Lagos. Fares, speed and time decide if you make it.","icon":"directions_bus","colors":["#F9A825","#33691E"],"xp":30,"stats":[{"id":"money","label":"Naira","icon":"payments","start":2000,"min":0,"format":"naira"},{"id":"time","label":"Minutes left","icon":"schedule","start":60,"format":"min"}],"cast":{"dad":{"name":"Daddy","role":"Your father","color":"#5D4037"},"cond":{"name":"The conductor","role":"Danfo bus","color":"#F9A825"},"tayo":{"name":"Tayo","role":"Your classmate","color":"#00695C"},"brt":{"name":"BRT officer","role":"Bus station","color":"#1565C0"}},"start":"intro","scenes":{"intro":{"kind":"say","text":"Your WAEC mock exam starts in 60 minutes, 12 km away in Ikeja. Daddy gives you {money}. \"Do not be late. Think before you board anything.\"","next":"cond1","speaker":"dad","bg":"road"},"cond1":{"kind":"say","text":"At the bus stop a conductor shouts. \"Danfo! Fare is ₦150 for the first 5 km, then ₦40 for every extra kilometre!\"","next":"q_fare","speaker":"cond","bg":"road"},"q_fare":{"kind":"input","text":"Your trip is 12 km. What is the danfo fare?","answer":430,"tolerance":0,"right":{"next":"mode","feedback":"Correct. The first 5 km cost ₦150. The remaining 7 km cost 7 x 40 = ₦280. Total: ₦430."},"wrong":{"next":"mode","feedback":"Not quite. The first 5 km cost ₦150. The remaining 7 km cost 7 x 40 = ₦280. Total: ₦430."},"speaker":"cond","bg":"road","unit":"₦","hint":"Fare for the first 5 km + 7 km at ₦40"},"mode":{"kind":"choice","text":"Tayo texts: \"Ojuelegba traffic is terrible at this hour, but the BRT has its own lane.\" How will you travel?","choices":[{"text":"Take the danfo through the traffic.","next":"danfo_ride","effects":{"money":-430},"learn":false,"feedback":"Cheapest, but Tayo warned you about the traffic. Time is worth planning for, not only money."},{"text":"Take the BRT lane bus (₦600).","next":"brt_ride","effects":{"money":-600},"learn":true,"feedback":"Smart. A dedicated lane makes the travel time predictable."},{"text":"Hire a keke for yourself (₦1,800).","next":"keke_ride","effects":{"money":-1800},"feedback":"Fast through side streets, but it takes most of your money."}],"speaker":"tayo","bg":"road"},"danfo_ride":{"kind":"say","text":"The danfo crawls through Ojuelegba traffic for 55 minutes. Then an accident ahead blocks the road for another 15.","next":"tayo_call","bg":"road","effects":{"time":-70}},"brt_ride":{"kind":"say","text":"At the BRT station an officer says: \"This bus covers 12 km at an average of 24 km per hour.\"","next":"q_brt","speaker":"brt","bg":"road"},"q_brt":{"kind":"input","text":"How many minutes will the BRT trip take? (time = distance / speed)","answer":30,"tolerance":0,"right":{"next":"brt_go","feedback":"Correct. 12 km / 24 km per hour = 0.5 hour = 30 minutes."},"wrong":{"next":"brt_go","feedback":"Not quite. 12 km / 24 km per hour = 0.5 hour, which is 30 minutes."},"speaker":"brt","bg":"road","unit":"min","hint":"Convert hours to minutes at the end"},"brt_go":{"kind":"say","text":"You ride the BRT lane, past the jam. It takes 30 minutes.","next":"tayo_call","bg":"road","effects":{"time":-30}},"keke_ride":{"kind":"say","text":"The keke weaves through the side streets. You arrive in 40 minutes, but the fare was heavy.","next":"tayo_call","bg":"road","effects":{"time":-40}},"tayo_call":{"kind":"say","text":"Your phone rings. It is Tayo. \"I am at the gate already. Bring me the textbook, and my brothers and I need to share the ₦1,800 transport money we borrowed, in the ratio 2 : 3 : 4.\"","next":"q_ratio","speaker":"tayo","bg":"school"},"q_ratio":{"kind":"input","text":"Share ₦1,800 in the ratio 2 : 3 : 4. How much is the largest share?","answer":800,"tolerance":0,"right":{"next":"lunch","feedback":"Correct. 2 + 3 + 4 = 9 parts. One part is 1,800 / 9 = ₦200, so the largest share is 4 x 200 = ₦800."},"wrong":{"next":"lunch","feedback":"Not quite. 2 + 3 + 4 = 9 parts. One part is 1,800 / 9 = ₦200, so the largest share is 4 x 200 = ₦800."},"speaker":"tayo","bg":"school","unit":"₦","hint":"Add the ratio parts first"},"lunch":{"kind":"choice","text":"You still have a few minutes before the hall opens. A food seller offers a snack for ₦200.","choices":[{"text":"Buy the snack. Hungry brains work badly.","next":"verdict","effects":{"money":-200,"time":-5}},{"text":"Skip it and go straight to the hall.","next":"verdict"}],"speaker":"tayo","bg":"school"},"verdict":{"kind":"branch","branches":[{"next":"end_late","if":[{"stat":"time","op":"<","value":0}]},{"next":"end_great","if":[{"stat":"money","op":">=","value":800},{"stat":"time","op":">=","value":25}]},{"next":"end_ok"}]},"end_great":{"kind":"end","title":"On time and calm","summary":"You compared your options with real numbers, arrived early and still had money in your pocket. That is how you beat Lagos traffic.","outcome":"good","bg":"school"},"end_ok":{"kind":"end","title":"You made it","summary":"You arrived in time, but the trip cost more than it needed to or left little spare time. Compare cost and time before you board.","outcome":"ok","bg":"school"},"end_late":{"kind":"end","title":"Too late","summary":"The hall doors have closed. Calculating the time before you travel is the best way to avoid this.","outcome":"bad","bg":"school"}}}''',
  r'''{"id":"suya_spot","title":"Start a Suya Spot","subject":"economics","level":"SS1","blurb":"Open a roadside suya stand. Costs, prices, demand and break-even decide whether you grow.","icon":"local_fire_department","colors":["#BF360C","#FF8F00"],"xp":35,"stats":[{"id":"money","label":"Naira","icon":"payments","start":50000,"min":0,"format":"naira"},{"id":"rep","label":"Reputation","icon":"star","start":0}],"cast":{"aunty":{"name":"Aunty Bose","role":"Business mentor","color":"#AD1457"},"musa":{"name":"Musa","role":"Master suya cutter","color":"#4E342E"},"chi":{"name":"Chidi","role":"Regular customer","color":"#00838F"}},"start":"intro","scenes":{"intro":{"kind":"say","text":"You have saved {money} and want to open a suya stand near the university gate. Aunty Bose, who runs three food businesses, agrees to coach you.","next":"costs","speaker":"aunty","bg":"street"},"costs":{"kind":"say","text":"\"Before you buy meat,\" she says, \"know your costs. Some stay the same however much you sell. Some change with every stick.\"","next":"q_type","speaker":"aunty","bg":"street"},"q_type":{"kind":"choice","text":"Which of these is a FIXED cost for the suya stand?","choices":[{"text":"Daily rent for the pitch: ₦6,000","next":"q_var","learn":true,"feedback":"Correct. Rent stays the same whether you sell 10 sticks or 100."},{"text":"Meat for each stick: ₦150","next":"q_var","learn":false,"feedback":"That is a variable cost. It rises with every stick you make. Rent for the pitch is the fixed cost."},{"text":"Packaging for each order","next":"q_var","learn":false,"feedback":"That is a variable cost. It grows with the number of orders. Rent for the pitch is the fixed cost."}],"speaker":"aunty","bg":"street"},"q_var":{"kind":"say","text":"Musa checks the numbers. \"Rent is ₦6,000 a day. Each stick costs ₦150 in meat, spice and charcoal. You will sell each stick for ₦350.\"","next":"q_bep","speaker":"musa","bg":"street"},"q_bep":{"kind":"input","text":"How many sticks must you sell each day just to cover your costs (break-even)? Each stick earns ₦350 - ₦150 = ₦200 towards the ₦6,000 rent.","answer":30,"tolerance":0,"right":{"next":"buy","feedback":"Correct. 6,000 / 200 = 30 sticks. Every stick after the 30th is profit.","effects":{"rep":1}},"wrong":{"next":"buy","feedback":"Not quite. Each stick leaves ₦200 after its own cost. 6,000 / 200 = 30 sticks to cover the rent. After that it is profit."},"speaker":"aunty","bg":"street","hint":"Fixed cost divided by profit per stick"},"buy":{"kind":"say","text":"You pay ₦14,000 for the first stock of meat, a grill, spices and charcoal, then open for business.","next":"week1","speaker":"musa","bg":"street","effects":{"money":-14000}},"week1":{"kind":"say","text":"Day one is slow, but by the weekend a crowd gathers. Chidi, a regular, says: \"Your suya is better than the stand by the bus stop, but they sell at ₦300.\"","next":"price","speaker":"chi","bg":"street"},"price":{"kind":"choice","text":"A cheaper rival is next door. What will you do?","choices":[{"text":"Cut your price to ₦300 to match them.","next":"cut","learn":false,"feedback":"Matching is understandable, but your profit per stick falls from ₦200 to ₦150, so you need 40 sticks a day to cover rent."},{"text":"Keep ₦350 and make the suya clearly better: more pepper, cleaner stand.","next":"quality","learn":true,"feedback":"Good. When your product is different and better, buyers will often pay more for it."},{"text":"Raise the price to ₦500 because your suya is the best.","next":"high","learn":false,"feedback":"Too bold. Higher price lowers demand, and most students cannot afford ₦500 daily."}],"speaker":"aunty","bg":"street"},"cut":{"kind":"say","text":"Sales rise a little, but each stick earns less. The week ends with small profit and a very tired Musa.","next":"q_demand","bg":"street","effects":{"money":3000,"rep":0}},"quality":{"kind":"say","text":"Word spreads. Students queue for your pepper mix and clean plates. The week brings in good profit.","next":"q_demand","bg":"street","effects":{"money":9000,"rep":2}},"high":{"kind":"say","text":"Curious customers try one stick and most do not come back. Many sticks go unsold.","next":"q_demand","bg":"street","effects":{"money":-2000,"rep":-1}},"q_demand":{"kind":"choice","text":"Exam week starts and the number of students buying suya doubles. According to the law of demand and supply, what will happen to the price if the supply stays the same?","choices":[{"text":"The price tends to rise.","next":"oppcost","learn":true,"feedback":"Correct. More demand with the same supply pushes prices up."},{"text":"The price tends to fall.","next":"oppcost","learn":false,"feedback":"Not quite. When demand rises and supply stays the same, the price tends to rise."},{"text":"Nothing changes.","next":"oppcost","learn":false,"feedback":"Not quite. When demand rises and supply stays the same, the price tends to rise."}],"speaker":"aunty","bg":"street"},"oppcost":{"kind":"choice","text":"A friend offers you a paid weekend job for ₦8,000, but you must close the stand. You think the stand would earn ₦6,000 that weekend. What is the opportunity cost of staying open?","choices":[{"text":"₦8,000 you give up by not taking the job.","next":"grow","learn":true,"feedback":"Correct. Opportunity cost is the value of the best alternative you give up."},{"text":"₦6,000 the stand would earn.","next":"grow","learn":false,"feedback":"Not quite. That is what you gain by staying open. The opportunity cost is the ₦8,000 you give up by not taking the job."}],"speaker":"aunty","bg":"street"},"grow":{"kind":"choice","text":"A month later you have saved some profit. How will you use it?","choices":[{"text":"Buy a second grill and hire Musa's cousin.","next":"verdict","effects":{"money":-9000,"rep":1},"feedback":"You invest to serve more customers at the same time."},{"text":"Keep it all as cash and change nothing.","next":"verdict","feedback":"Safe, but the business does not grow."},{"text":"Spend it on new shoes and a big party.","next":"verdict","effects":{"money":-8000,"rep":-1},"feedback":"That is consumption, not investment. The stand gets nothing from it."}],"speaker":"aunty","bg":"street"},"verdict":{"kind":"branch","branches":[{"next":"end_great","if":[{"stat":"rep","op":">=","value":4}]},{"next":"end_ok","if":[{"stat":"rep","op":">=","value":1}]},{"next":"end_bad"}]},"end_great":{"kind":"end","title":"A growing business","summary":"You worked out your costs, held your price with a better product and invested your profit. You are on your way to a third stand.","outcome":"good","bg":"street"},"end_ok":{"kind":"end","title":"A steady stand","summary":"Your business survives and pays you. Practise break-even and pricing and it will grow faster.","outcome":"ok","bg":"street"},"end_bad":{"kind":"end","title":"Back to the drawing board","summary":"Poor pricing and spending hurt the stand. Know your costs, understand demand and invest profit back into the business.","outcome":"bad","bg":"street"}}}''',
  r'''{"id":"clean_water","title":"Clean Water for Ajegunle","subject":"bst","level":"JSS3","blurb":"A cholera scare hits your street. Lead the community to safe water and good hygiene.","icon":"water_drop","colors":["#0277BD","#00ACC1"],"xp":35,"stats":[{"id":"health","label":"Community health","icon":"health_and_safety","start":50,"min":0,"max":100},{"id":"funds","label":"Funds","icon":"payments","start":120000,"min":0,"format":"naira"},{"id":"trust","label":"Trust","icon":"groups","start":0}],"cast":{"nurse":{"name":"Nurse Amina","role":"Clinic nurse","color":"#00796B"},"baale":{"name":"Baale","role":"Community head","color":"#5D4037"},"ife":{"name":"Ife","role":"Your classmate","color":"#7B1FA2"}},"start":"intro","scenes":{"intro":{"kind":"say","text":"Several people on your street have fallen ill with severe diarrhoea. Nurse Amina asks you, as the school health club leader, to help. \"We suspect cholera,\" she says. \"It spreads through dirty water.\"","next":"disease","speaker":"nurse","bg":"clinic"},"disease":{"kind":"choice","text":"Which of these is the most likely cause of the outbreak?","choices":[{"text":"Drinking water contaminated with germs from waste.","next":"source","learn":true,"feedback":"Correct. Cholera and typhoid spread through water or food contaminated with faeces."},{"text":"Breathing smoke from burning refuse.","next":"source","learn":false,"feedback":"Smoke can harm lungs, but cholera spreads through contaminated water and food."},{"text":"Mosquito bites.","next":"source","learn":false,"feedback":"Mosquitoes spread malaria. Cholera spreads through contaminated water and food."}],"speaker":"nurse","bg":"clinic"},"source":{"kind":"say","text":"You and Ife trace the problem. Most families fetch water from an open well near a blocked drain. The Baale agrees to meet you at the well.","next":"baale","speaker":"ife","bg":"well"},"baale":{"kind":"say","text":"\"We have ₦120,000 saved for community projects,\" the Baale says. \"There are 240 households. Tell us what to do first.\"","next":"q_litres","speaker":"baale","bg":"well"},"q_litres":{"kind":"input","text":"Each household needs about 20 litres of water a day. How many litres does the whole community need each day?","answer":4800,"tolerance":0,"right":{"next":"tanks","feedback":"Correct. 240 households x 20 litres = 4,800 litres a day.","effects":{"trust":1}},"wrong":{"next":"tanks","feedback":"Not quite. 240 x 20 = 4,800 litres a day."},"speaker":"baale","bg":"well","unit":"L","hint":"240 x 20"},"tanks":{"kind":"input","text":"Clean water will be stored in tanks that each hold 1,000 litres. How many tanks are needed to store one day's water?","answer":5,"tolerance":0,"right":{"next":"first","feedback":"Correct. 4,800 / 1,000 = 4.8, so you round up to 5 tanks. Four would not be enough.","effects":{"trust":1}},"wrong":{"next":"first","feedback":"Not quite. 4,800 / 1,000 = 4.8, and you must round up to 5 tanks because 4 would not be enough."},"speaker":"ife","bg":"well","hint":"You cannot buy part of a tank"},"first":{"kind":"choice","text":"What should you do first to protect the community right now?","choices":[{"text":"Tell families to boil drinking water before use and seal the well with a cover.","next":"educate","effects":{"health":20,"funds":-5000},"learn":true,"feedback":"Correct. Boiling kills the germs, and covering the well stops more contamination."},{"text":"Ignore the well and wait for the clinic to fix everything.","next":"educate","effects":{"health":-15,"trust":-1},"learn":false,"feedback":"Waiting lets the outbreak spread. Quick, simple actions protect people straight away."},{"text":"Buy sweets and drinks for everyone.","next":"educate","effects":{"health":-5,"funds":-20000},"learn":false,"feedback":"That does nothing about the unsafe water, and it uses up your funds."}],"speaker":"nurse","bg":"well"},"educate":{"kind":"choice","text":"Next, how should you spread the message about handwashing and safe water?","choices":[{"text":"Hold a street meeting with songs and demonstrations, and give out soap.","next":"plan","effects":{"health":15,"funds":-8000,"trust":2},"learn":true,"feedback":"Great. People remember what they see and practise, and soap makes it easy to start."},{"text":"Post one notice on a wall and hope people read it.","next":"plan","effects":{"health":3},"learn":false,"feedback":"Many people will never see it. Face-to-face teaching works far better."}],"speaker":"ife","bg":"street"},"plan":{"kind":"choice","text":"Now plan a lasting solution with the remaining funds.","choices":[{"text":"Fix the drain, build a covered borehole and add a hand-washing station.","next":"check","effects":{"health":25,"funds":-90000,"trust":2},"learn":true,"feedback":"A strong choice. You remove the source of contamination and give people safe water and a place to wash hands.","if":[{"stat":"funds","op":">=","value":90000}]},{"text":"Only buy bottled water for a few weeks.","next":"check","effects":{"health":5,"funds":-40000},"learn":false,"feedback":"It helps briefly, but when the bottles run out the real problem is still there."},{"text":"Dig another open well beside the first.","next":"check","effects":{"health":-10,"funds":-30000},"learn":false,"feedback":"Another open well near the same drain will be contaminated too."}],"speaker":"baale","bg":"well"},"check":{"kind":"branch","branches":[{"next":"end_great","if":[{"stat":"health","op":">=","value":95}]},{"next":"end_ok","if":[{"stat":"health","op":">=","value":55}]},{"next":"end_bad"}]},"end_great":{"kind":"end","title":"The street is safe","summary":"Cases stop within two weeks. You found the cause, protected people straight away, taught them well and built a lasting fix. The Baale names the new borehole after your health club.","outcome":"good","bg":"well"},"end_ok":{"kind":"end","title":"Progress, but not finished","summary":"The outbreak slows, but the community is still at some risk. Remove the source of contamination, not only the symptoms.","outcome":"ok","bg":"well"},"end_bad":{"kind":"end","title":"Still at risk","summary":"More families fall ill. Safe water, clean sanitation and handwashing together stop waterborne disease. Try again with those three in mind.","outcome":"bad","bg":"well"}}}''',
];
